package org.apache.commons.math3.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.analysis.UnivariateFunction;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.optimization.ConvergenceChecker;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.univariate.GoalType.MAXIMIZE;
import org.apache.commons.math3.optimization.univariate.GoalType.MINIMIZE;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BrentOptimizer.doOptimize().
 * Since doOptimize is protected, we use a subclass to expose it for testing.
 */
public class BrentOptimizer_doOptimize_TriageGen2Test {

    private static final double EPSILON = 1e-6;

    /**
     * Test subclass to access the protected doOptimize method.
     */
    private static class TestableBrentOptimizer extends BrentOptimizer {
        private final UnivariateFunction function;

        public TestableBrentOptimizer(double rel, double abs, UnivariateFunction function) {
            super(rel, abs);
            this.function = function;
        }

        public TestableBrentOptimizer(double rel, double abs, UnivariateFunction function, ConvergenceChecker<UnivariatePointValuePair> checker) {
            super(rel, abs, checker);
            this.function = function;
        }

        @Override
        protected double computeObjectiveValue(double x) {
            return function.value(x);
        }

        public UnivariatePointValuePair callDoOptimize() {
            return doOptimize();
        }
    }

    @Test
    public void testMinimizeParabola() {
        // f(x) = (x-2)^2 + 5. Min at x=2, f(x)=5.
        UnivariateFunction function = x -> Math.pow(x - 2, 3 - 1) + 5; // Using pow for variety
        // Simpler:
        function = x -> (x - 2) * (x - 2) + 5;

        TestableBrentOptimizer optimizer = new TestableBrentOptimizer(1e-10, 1e-10, function);
        // Set bounds via constructor logic (BrentOptimizer uses getMin/getMax which usually come from setBounds)
        // Since we can't call setBounds easily in this snippet without knowing the internal state, 
        // we assume the optimizer is initialized with appropriate bounds.
        // However, BrentOptimizer requires setBounds to be called.

        // Let's simulate the optimizer behavior by providing a function and bounds.
        // Since the provided code snippet relies on getMin(), getStartValue(), etc., 
        // we must ensure the optimizer is properly configured.

        optimizer.setOptimizationType(MINIMIZE);
        // Note: BrentOptimizer requires setBounds(min, max)
        // We use a helper to create a configured optimizer.
    }

    // Re-implementing test logic to be more robust given the class structure

    @Test
    public void testMinimizeSimple() {
        UnivariateFunction f = x -> (x - 3) * (x - 3);
        TestableBrentOptimizer optimizer = new TestableBrentOptimizer(1e-8, 1e-8, f);
        optimizer.setOptimizationType(MINIMIZE);
        optimizer.setBounds(-10, 10);

        UnivariatePointValuePair result = optimizer.callDoOptimize();
        assertEquals(3.0, result.getPoint(), 1e-5);
        assertEquals(0.0, result.getValue(), 1e-5);
    }

    @Test
    public void testMaximizeSimple() {
        UnivariateFunction f = x -> -(x - 5) * (x - 5) + 10;
        TestableBrentOptimizer optimizer = new TestableBrentOptimizer(1e-8, 1e-8, f);
        optimizer.setOptimizationType(MAXIMIZE);
        optimizer.setBounds(0, 10);

        UnivariatePointValuePair result = optimizer.callDoOptimize();
        assertEquals(5.0, result.getPoint(), 1e-5);
        assertEquals(10.0, result.getValue(), 1e-5);
    }

    @Test
    public void testReverseBounds() {
        // Tests the if (lo < hi) else logic
        UnivariateFunction f = x -> (x - 1) * (x - 1);
        TestableBrentOptimizer optimizer = new TestableBrentOptimizer(1e-8, 1e-8, f);
        optimizer.setOptimizationType(MINIMIZE);
        optimizer.setBounds(10, -10); // hi < lo

        UnivariatePointValuePair result = optimizer.callDoOptimize();
        assertEquals(1.0, result.getPoint(), 1e-5);
    }

    @Test
    public void testConvergenceChecker() {
        UnivariateFunction f = x -> (x - 2) * (x - 2);
        ConvergenceChecker<UnivariatePointValuePair> mockChecker = mock(ConvergenceChecker.class);

        // Force convergence on the second iteration
        when(mockChecker.converged(org.mockito.ArgumentMatchers.anyInt(), org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any()))
            .thenReturn(false)
            .thenReturn(true);

        TestableBrentOptimizer optimizer = new TestableBrentOptimizer(1e-8, 1e-8, f, mockChecker);
        optimizer.setOptimizationType(MINIMIZE);
        optimizer.setBounds(0, 5);

        UnivariatePointValuePair result = optimizer.callDoOptimize();
        // Result should be valid even if stopped early by checker
        assertTrue(result != null);
    }

    @Test
    public void testParabolicInterpolationStep() {
        // A function that is very smooth to trigger parabolic interpolation
        UnivariateFunction f = x -> Math.pow(x, 4) - 4 * x * x + x;
        TestableBrentOptimizer optimizer = new TestableBrentOptimizer(1e-10, 1e-10, f);
        optimizer.setOptimizationType(MINIMIZE);
        optimizer.setBounds(-5, 5);

        UnivariatePointValuePair result = optimizer.callDoOptimize();
        // Just ensuring it converges without crashing and follows the logic
        assertTrue(result.getValue() < f.value(0));
    }

    @Test
    public void testGoldenSectionStep() {
        // Use a non-smooth function or a very narrow interval to force golden section
        UnivariateFunction f = x -> Math.abs(x - 0.5);
        TestableBrentOptimizer optimizer = new TestableBrentOptimizer(1e-8, 1e-8, f);
        optimizer.setOptimizationType(MINIMIZE);
        optimizer.setBounds(0, 1);

        UnivariatePointValuePair result = optimizer.callDoOptimize();
        assertEquals(0.5, result.getPoint(), 1e-5);
    }

    @Test
    public void testSmallTolerance() {
        // Tests the "Update by at least tol1" logic
        UnivariateFunction f = x -> (x - 1) * (x - 1);
        TestableBrentOptimizer optimizer = new TestableBrentOptimizer(1e-15, 1e-15, f);
        optimizer.setOptimizationType(MINIMIZE);
        optimizer.setBounds(0, 2);

        UnivariatePointValuePair result = optimizer.callDoOptimize();
        assertEquals(1.0, result.getPoint(), 1e-10);
    }

    @Test
    public void testExtremeValues() {
        // Tests precision and edge cases
        UnivariateFunction f = x -> Math.exp(x);
        TestableBrentOptimizer optimizer = new TestableBrentOptimizer(1e-8, 1e-8, f);
        optimizer.setOptimizationType(MINIMIZE);
        optimizer.setBounds(-10, 10);

        UnivariatePointValuePair result = optimizer.callDoOptimize();
        assertEquals(-10.0, result.getPoint(), 1e-5);
    }
}
